import math

def is_power_of_p(n, p):
    """Checks if n is a positive power of p (p^x where x >= 1)."""
    if n <= 0:
        return False
    # Since p >= 3, we check if n is divisible by p repeatedly.
    if n == 1:
        return False # Assuming x >= 1 based on typical problem constraints for powers

    temp_n = n
    while temp_n > 1:
        if temp_n % p != 0:
            return False
        temp_n //= p
    return True

def search_solutions():
    primes = [5, 7, 11, 13]
    max_ab = 20
    solutions = []

    print("Starting brute force search...")

    for p in primes:
        for a in range(1, max_ab + 1):
            for b in range(a, max_ab + 1):
                # Condition 1: a^(p-1) + b = p^x
                try:
                    N1 = a**(p - 1) + b
                except OverflowError:
                    # Skip if calculation is too large for standard integer types
                    continue 

                cond1 = is_power_of_p(N1, p)

                if not cond1:
